package com.airesumebuilder.feature.audit.listener;import com.airesumebuilder.events.*;import com.airesumebuilder.feature.audit.service.AuditService;import java.util.Map;import org.springframework.stereotype.Component;import org.springframework.transaction.event.*;
@Component public class ResumeAuditListener{private final AuditService audit;public ResumeAuditListener(AuditService a){audit=a;}@TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT,fallbackExecution=true)public void created(ResumeCreatedEvent e){audit.record(e.userId(),"Resume",e.resumeId(),"CREATED",Map.of("resumeId",e.resumeId()));}@TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT,fallbackExecution=true)public void updated(ResumeUpdatedEvent e){audit.recordChange(e.userId(),"Resume",e.resumeId(),"UPDATED",e.before(),e.after());}@TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT,fallbackExecution=true)public void deleted(ResumeDeletedEvent e){audit.recordChange(e.userId(),"Resume",e.resumeId(),"DELETED",e.before(),Map.of("deleted",true));}}
